SELECT FROM app_user u WHERE u.status = 1 AND u.id != #{viewerId}
AND (u.nickname LIKE CONCAT('%', #{keyword}, '%') OR u.handle LIKE CONCAT('%', #{keyword}, '%') OR u.city LIKE CONCAT('%', #{keyword}, '%') OR u.role LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY u.followers_count DESC, u.id LIMIT #{limit}
